"""Represent a dictionary with human-friendly text.

    Assuming d is of type dict, the output should be syntactically
    equivalent to repr(d), but with each key-value pair on its own,
    indented line.
    """
def pretty_dict_repr(d: Any) -> object {
    lines = ['    {0!r}: {1!r},'.format(k, v) for (k, v) in sorted(d.items())];
    return '\n'.join((['{'] + lines + ['}']));
}

"""Reads to the next divider line.

    Read lines are returned, 'lines' is reduced to everything remaining.
    """
def read_table(lines: Any) -> object {
    table_lines = [];
    while len(lines) {
        popline = lines[0];
        lines = lines[1:];
        if (popline[:6] == "======") {
            break;
        }
        table_lines += [popline];
    }
    return table_lines;
}

